-- Exact five-minute menu durations/buffers, with existing quarter-hour starts.
ALTER TABLE reserve_services DROP CONSTRAINT IF EXISTS reserve_services_minutes_check;
ALTER TABLE reserve_services ADD CONSTRAINT reserve_services_minutes_check CHECK(minutes>0 AND minutes%5=0);
ALTER TABLE reserve_services DROP CONSTRAINT IF EXISTS reserve_services_buffer_check;
ALTER TABLE reserve_services ADD CONSTRAINT reserve_services_buffer_check CHECK(buffer>=0 AND buffer%5=0);
-- A retired request cannot create a booking after a customer recovers/reloads.
-- This stores no payload, notes or contacts. Both recovery and booking hold the
-- same reserve_users row lock. Retain fences to reject delayed old requests.
CREATE TABLE IF NOT EXISTS reserve_booking_request_fences (
 client_id text NOT NULL REFERENCES reserve_users(id) ON DELETE CASCADE,
 request_key uuid NOT NULL,
 created_at timestamptz NOT NULL DEFAULT now(),
 PRIMARY KEY(client_id,request_key)
);
ALTER TABLE reserve_booking_request_fences ENABLE ROW LEVEL SECURITY;
